<script setup lang="ts">
import { PhMagnifyingGlass,PhPackage,PhArrowRight,PhCrosshair } from '@phosphor-icons/vue'
import { availableStock,stockState,formatNumber,type InventoryPart } from '../data/operations'
import type { Finding } from '../types/findings'
import type { MaterialDialogTarget } from '../types/materialRequests'
import {inventoryWithRequests} from '../utils/materialRequests'
import type { RecordDetails,WorkspaceNavigation } from '../types/workspace'
const props=defineProps<{viewerReady:boolean;findings:Finding[];storageReady:boolean;storageError:string;navigation?:WorkspaceNavigation|null}>()
const inventoryParts=computed(()=>inventoryWithRequests(props.findings))
const emit=defineEmits<{inspect:[detail:RecordDetails];locate:[sourceName:string];materialAction:[target:MaterialDialogTarget];openWork:[id:string]}>()
const query=ref(''),state=ref('all'),category=ref('all')
const labels={available:'Tersedia',low:'Stok rendah',empty:'Kosong'}
const categories=[...new Set(inventoryParts.value.map(p=>p.category))]
const filtered=computed(()=>inventoryParts.value.filter(p=>(state.value==='all'||(state.value==='attention'?stockState(p)!=='available':stockState(p)===state.value))&&(category.value==='all'||p.category===category.value)&&`${p.name} ${p.partNumber} ${p.location}`.toLocaleLowerCase('id').includes(query.value.trim().toLocaleLowerCase('id'))))
watch(()=>props.navigation?.id,()=>{if(!props.navigation){query.value='';category.value='all';state.value='all'}else if(props.navigation.tab==='inventory'){query.value='';category.value='all';state.value=props.navigation.stock??'all'}},{immediate:true})
function inspect(part:InventoryPart){emit('inspect',{eyebrow:'INVENTORI / DATA CONTOH',title:part.name,description:part.note,fields:[{label:'Part number contoh',value:part.partNumber},{label:'Kategori',value:part.category},{label:'Lokasi',value:part.location},{label:'Stok fisik',value:`${part.quantity} ${part.unit}`},{label:'Dialokasikan',value:`${part.reserved} ${part.unit}`},{label:'Tersedia',value:`${availableStock(part)} ${part.unit}`},{label:'Ambang stok contoh',value:`${part.minimum} ${part.unit}`}],note:'Stok contoh mengikuti permintaan lokal. Part number dan kesesuaian pemasangan belum diverifikasi; belum terhubung ke gudang operator.'})}
</script>
<template>
 <section class="operations-page inventory-page" aria-labelledby="inventory-title">
  <header class="operations-heading"><div><span class="operations-eyebrow">C208 / MATERIAL & SUKU CADANG</span><h2 id="inventory-title">Inventori sparepart</h2><p>Lihat ketersediaan, alokasi, dan lokasi penyimpanan material pesawat demo.</p></div><span class="data-origin">Data contoh</span></header>
  <p class="operations-data-note"><PhPackage :size="18" /> Semua item dan part number berawalan DEMO adalah data simulasi, belum terhubung ke gudang operator.</p>
  <div class="operations-metrics"><div><span>Jenis item</span><strong>{{ inventoryParts.length }}</strong><small>Dalam katalog contoh</small></div><div><span>Perlu perhatian</span><strong>{{ inventoryParts.filter(p=>stockState(p)!=='available').length }}</strong><small>Stok rendah atau kosong</small></div><div><span>Item dialokasikan</span><strong>{{ inventoryParts.filter(p=>p.reserved>0).length }}</strong><small>Memiliki alokasi contoh</small></div><div><span>Lokasi penyimpanan</span><strong>{{ new Set(inventoryParts.map(p=>p.location)).size }}</strong><small>Rak dan lemari</small></div></div>
  <MaterialRequestsQueue :navigation="navigation" :findings="findings" :storage-ready="storageReady" :storage-error="storageError" @action="emit('materialAction',$event)" @open-work="emit('openWork',$event)" />
  <div class="operations-section-heading"><div><h3>Ketersediaan material</h3><p>Tersedia = stok fisik dikurangi alokasi.</p></div><span>{{ filtered.length }} item</span></div>
  <div class="operations-filters"><label class="operations-search"><span class="sr-only">Cari sparepart</span><PhMagnifyingGlass :size="18" /><input v-model="query" aria-label="Cari sparepart" placeholder="Cari nama, part number, atau lokasi…" /></label><label class="operations-select"><span>Kategori</span><select v-model="category" aria-label="Filter kategori sparepart"><option value="all">Semua kategori</option><option v-for="label in categories" :key="label">{{ label }}</option></select></label><label class="operations-select"><span>Ketersediaan</span><select v-model="state" aria-label="Filter stok sparepart"><option value="all">Semua stok</option><option value="attention">Rendah / kosong</option><option v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</option></select></label></div>
  <div v-if="!filtered.length" class="operations-empty"><PhPackage :size="32" /><h3>Sparepart tidak ditemukan</h3><p>Ubah pencarian atau filter ketersediaan.</p><button class="button" @click="query='';state='all';category='all'">Hapus filter</button></div>
  <div v-else class="operations-table-wrap" tabindex="0" aria-label="Daftar inventori, geser bila diperlukan"><table class="operations-table inventory-table"><caption class="sr-only">Inventori sparepart contoh untuk C208 Demo</caption><thead><tr><th>Item / part number</th><th>Lokasi</th><th>Fisik</th><th>Alokasi</th><th>Tersedia</th><th>Status</th><th><span class="sr-only">Tindakan</span></th></tr></thead><tbody><tr v-for="part in filtered" :key="part.id" :data-part-id="part.id"><td><strong>{{ part.name }}</strong><small class="record-code">{{ part.partNumber }}</small><small>{{ part.category }}</small></td><td>{{ part.location }}</td><td class="numeric">{{ formatNumber(part.quantity) }}<small>{{ part.unit }}</small></td><td class="numeric">{{ part.reserved }}</td><td class="numeric available-quantity">{{ availableStock(part) }}</td><td><span class="operation-status" :class="stockState(part)">{{ labels[stockState(part)] }}</span></td><td><div class="record-table-actions"><button class="button subtle" :aria-label="`Detail ${part.name}`" @click="inspect(part)">Detail<PhArrowRight :size="15" /></button><button v-if="part.sourceName" class="icon-button" :aria-label="`Lihat area ${part.name} pada model`" :disabled="!viewerReady" @click="emit('locate',part.sourceName)"><PhCrosshair :size="19" /></button></div></td></tr></tbody></table></div>
 </section>
</template>
